+/**
+ * Collapse multi-line property types (e.g. `validateOrderability?: (\n  variant,\n  ...\n)`)
+ * into single lines so lineRe can capture the full type. Tracks `(` / `)` depth while
+ * skipping characters inside single/double-quoted strings and line/block comments so that
+ * literals like `'('` or `// )` cannot affect depth or property extraction.
+ */
+function normaliseBody(body) {
+  const lines = body.split('\n')
+  const out = []
+  let depth = 0
+  let accum = null
+  let inBlock = false // inside /* ... */
+
+  for (const line of lines) {
+    let inSingle = false
+    let inDouble = false
+    let i = 0
+    while (i < line.length) {
+      const ch = line[i]
+      if (inBlock) {
+        if (ch === '*' && line[i + 1] === '/') { inBlock = false; i += 2; continue }
+      } else if (inSingle) {
+        if (ch === '\\') { i += 2; continue } // skip escape sequence
+        if (ch === "'") inSingle = false
+      } else if (inDouble) {
+        if (ch === '\\') { i += 2; continue } // skip escape sequence
+        if (ch === '"') inDouble = false
+      } else {
+        if (ch === '/' && line[i + 1] === '/') break // line comment — ignore rest of line
+        if (ch === '/' && line[i + 1] === '*') { inBlock = true; i += 2; continue }
+        if (ch === "'") { inSingle = true }
+        else if (ch === '"') { inDouble = true }
+        else if (ch === '(') depth++
+        else if (ch === ')') depth--
+      }
+      i++
+    }
+
+    if (accum !== null) {
+      accum = `${accum} ${line.trim()}`
+      if (depth === 0) { out.push(accum); accum = null }
+    } else if (depth > 0) {
+      accum = line
+    } else {
+      out.push(line)
+    }
+  }
+  if (accum !== null) out.push(accum)
+  return out.join('\n')
+}
