39	const SWATCH_IMAGE_QUALITY = 60;
40	
41	const ZIMM_COLOUR_SWATCHES_RECIPE = 'ZimmColourSwatches';
42	
43	/**
44	 * Appends SFCC Dynamic Image Service sizing params to a resolved swatch URL. Equivalent to
45	 * the `[?sw={width}&q=60]` bracket notation the base app feeds to DynamicImage, but for a
46	 * fixed-size swatch there is only one width to serve, so DynamicImage's responsive
47	 * srcSet/sizes machinery would be dead weight. Picks the separator defensively — `link`
48	 * (the fallback when `disBaseLink` is absent) can already carry a query string.
49	 */
50	const sizedSwatchUrl = (url: string) => {
51	  if (url.startsWith('data:')) return url;
52	  return `${url}${url.includes('?') ? '&' : '?'}sw=${SWATCH_IMAGE_WIDTH}&q=${SWATCH_IMAGE_QUALITY}`;
53	};
54	
55	type ColourSwatchesProps = {
56	  /** All available colour variants for this product */
57	  variants: readonly ColourVariant[];
58	  /** Currently selected colour value — omit or pass undefined if none selected */
59	  selectedValue?: string;
60	  /** Called when the shopper clicks or keyboard-selects a swatch */
61	  onSelect: (value: string) => void;
62	};
63	
64	/**
65	 * Renders a radiogroup of colour swatches for the PDP. Pure UI — receives fully
66	 * resolved props from the parent page; does not call any SDK hooks.
67	 */
68	const ColourSwatches = ({ variants, selectedValue, onSelect }: ColourSwatchesProps) => {
69	  const intl = useIntl();
70	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCHES_RECIPE, {});
71	  const swatchRefs = useRef<(HTMLButtonElement | null)[]>([]);
72	  // pendingFocusIndexRef: position within the page to focus after a page change triggered
73	  // by keyboard navigation. Set in handleKeyDown, consumed in the page useEffect.
74	  const pendingFocusIndexRef = useRef<number | null>(null);
75	  const [page, setPage] = useState(0);
76	
77	  // AC5: a colour is only offered if it has a resolved swatch image AND is orderable.
78	  // An unavailable/disabled colour is withheld entirely rather than shown in a disabled
79	  // state — confirmed by the BA 2026-08-21, superseding the earlier `opacity: 0.4` reading.
80	  // Memoised to avoid repeated filter passes on every render and to keep pageCount stable
81	  // across renders where variants hasn't changed.
82	  // Type predicate so `imageUrl` narrows to `string` in the render below — Array.filter
83	  // alone would leave it `string | undefined` and force an assertion at the img src.
84	  const swatchVariants = useMemo(
85	    () => variants.filter((v): v is OfferedColourVariant => Boolean(v.imageUrl) && v.orderable),
86	    [variants],
87	  );
88	  // Always-current ref so the auto-advance effect can read swatchVariants without depending
89	  // on it — if it depended on swatchVariants, any parent re-render that creates a new
90	  // variants array identity would reset a chevron-navigated page back to the selected
91	  // colour's page. The ref is updated synchronously during render, before effects run.
92	  const swatchVariantsRef = useRef(swatchVariants);
93	  swatchVariantsRef.current = swatchVariants;
94	  // AC1: single colour → text label only, no swatch row.
95	  const showSwatches = swatchVariants.length > 1;
96	
97	  const pageCount = Math.ceil(swatchVariants.length / PAGE_SIZE);
98	  const showPagination = swatchVariants.length > PAGE_SIZE;
99	  const pagedVariants = swatchVariants.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
100	
101	  // Resolve from swatchVariants (not variants) so a withheld colour's name is never shown
102	  // in the label — AC5 requires withheld colours not to be surfaced at all.
103	  const selectedName = swatchVariants.find((v) => v.value === selectedValue)?.name;
104	  // AC1: when there is exactly one offered colour, show its name even before a selection
105	  // is made. Keyed off swatchVariants, not variants — a product whose other colours were
106	  // all withheld is a single-colour product as far as the shopper can tell.
107	  const labelName = selectedName ?? (swatchVariants.length === 1 ? swatchVariants[0]?.name : undefined);
108	
109	  // Stable primitive derived from the offered set's content (not identity). Changes when a
110	  // colour gains/loses its image or orderable status; stays the same when a parent re-render
111	  // produces a new variants array reference with the same logical values.
112	  const swatchVariantsKey = JSON.stringify(swatchVariants.map((v) => v.value));
113	
114	  // When the selected colour is on a different page (e.g. deep link with ?color=), advance
115	  // to that page automatically so the selected swatch is always visible.
116	  // Deps: selectedValue + swatchVariantsKey — the key re-fires when the offered set changes
117	  // content so page is recalculated; swatchVariants is still read via ref so identity-only
118	  // parent re-renders do not reset a chevron-navigated page.
119	  useEffect(() => {
120	    if (selectedValue === undefined) return;
121	    const globalIndex = swatchVariantsRef.current.findIndex((v) => v.value === selectedValue);
122	    if (globalIndex === -1) return;
123	    setPage(Math.floor(globalIndex / PAGE_SIZE));
124	  }, [selectedValue, swatchVariantsKey]);
125	
126	  // Clamp page to a valid range when swatchVariants shrinks (e.g. variants prop changes).
127	  useEffect(() => {
128	    setPage((p) => Math.min(p, Math.max(0, pageCount - 1)));
129	  }, [pageCount]);
130	
131	  // After a page change triggered by keyboard navigation, focus the pending swatch.
132	  useEffect(() => {
133	    if (pendingFocusIndexRef.current !== null) {
134	      swatchRefs.current[pendingFocusIndexRef.current]?.focus();
135	      pendingFocusIndexRef.current = null;
136	    }
137	  }, [page]);
138	
139	  const handleKeyDown = (e: React.KeyboardEvent) => {
140	    if (swatchVariants.length === 0) return;
141	
142	    // Navigate from the actually-focused swatch, not the selected one. When the user
143	    // chevron-navigates to a different page from the selected colour's page, the focused
144	    // swatch differs from selectedValue — using selectedValue would compute the wrong
145	    // next position and jump unexpectedly across pages. Fall back to selectedValue when
146	    // focus is on something that isn't a swatch (shouldn't happen, but guards the cast).
147	    const focusedValue = (e.target as HTMLElement).closest<HTMLButtonElement>('[role="radio"]')?.dataset.swatchValue;
148	    const currentIndex = swatchVariants.findIndex((v) => v.value === (focusedValue ?? selectedValue));
149	    const isForward = e.key === 'ArrowRight' || e.key === 'ArrowDown';
150	    const isBackward = e.key === 'ArrowLeft' || e.key === 'ArrowUp';
151	    if (!isForward && !isBackward) return;
152	
153	    e.preventDefault();
154	
155	    let nextIndex: number;
156	    if (currentIndex === -1) {
157	      // Nothing selected: forward → first, backward → last.
158	      // Must NOT fall through to modulo maths — with currentIndex === -1,
159	      // backward would compute (len - 2), landing on the second-to-last swatch.
160	      nextIndex = isForward ? 0 : swatchVariants.length - 1;
161	    } else {
162	      nextIndex = isForward
163	        ? (currentIndex + 1) % swatchVariants.length
164	        : (currentIndex - 1 + swatchVariants.length) % swatchVariants.length;
165	    }
166	
167	    onSelect(swatchVariants[nextIndex].value);
168	
169	    const nextPage = Math.floor(nextIndex / PAGE_SIZE);
170	    const nextIndexOnPage = nextIndex % PAGE_SIZE;
171	
172	    if (nextPage !== page) {
173	      // Page change: set pending focus so the useEffect above applies it after re-render.
174	      setPage(nextPage);
175	      pendingFocusIndexRef.current = nextIndexOnPage;
176	    } else {
177	      swatchRefs.current[nextIndexOnPage]?.focus();
178	    }
179	  };
180	
181	  // Tab stop: the selected swatch if it's on the current page; otherwise the first swatch
182	  // on the current page, keeping a single tab stop inside the radiogroup at all times.
183	  const selectedOnCurrentPage = pagedVariants.some((v) => v.value === selectedValue);
184	
185	  return (
186	    <chakra.div __css={styles.container} data-testid="pdp-colour-swatches">
187	      <chakra.div __css={styles.labelRow}>
188	        {/* caption-strong: caption textStyle + fontWeight medium (no captionStrong key in typography.ts) */}
189	        <chakra.span __css={styles.label}>
190	          {intl.formatMessage({ id: 'colour_swatches.label', defaultMessage: 'Colour:' })}
191	        </chakra.span>
192	        {labelName && (
193	          // testid rather than a role: this is a bare span with no semantics of its own,
194	          // and E2E needs to assert the selected colour's name independently of the swatches.
195	          <chakra.span __css={styles.selectedName} data-testid="pdp-colour-selected-name">
196	            {labelName}
197	          </chakra.span>
198	        )}
199	        {showPagination && (
200	          // Chevron buttons: 24×24px hit area, 16×16px icon — Figma node 40000307-13867.
201	          <chakra.div
202	            __css={styles.paginationGroup}
203	            role="group"
204	            aria-label={intl.formatMessage({
205	              id: 'colour_swatches.pagination.group_label',
206	              defaultMessage: 'Colour swatch pages',
207	            })}
208	          >
209	            <chakra.button
210	              __css={styles.chevronButton}
211	              type="button"
212	              aria-label={intl.formatMessage({
213	                id: 'colour_swatches.pagination.previous',
214	                defaultMessage: 'Previous colours',
215	              })}
216	              onClick={() => setPage((p) => Math.max(0, p - 1))}
217	              disabled={page === 0}
218	            >
219	              {/* audit-allow: 16px icon size; no zimm token for swatch control dimensions */}
220	              <ChevronLeftIcon boxSize="16px" />
221	            </chakra.button>
222	            <chakra.button
223	              __css={styles.chevronButton}
224	              type="button"
225	              aria-label={intl.formatMessage({ id: 'colour_swatches.pagination.next', defaultMessage: 'Next colours' })}
226	              onClick={() => setPage((p) => Math.min(pageCount - 1, p + 1))}
227	              disabled={page === pageCount - 1}
228	            >
229	              {/* audit-allow: 16px icon size; no zimm token for swatch control dimensions */}
230	              <ChevronRightIcon boxSize="16px" />
231	            </chakra.button>
232	          </chakra.div>
233	        )}
234	      </chakra.div>
235	
236	      {showSwatches && (
237	        <chakra.div
238	          __css={styles.swatchGroup}
239	          role="radiogroup"
240	          aria-label={intl.formatMessage({ id: 'colour_swatches.group.label', defaultMessage: 'Colour' })}
241	          onKeyDown={handleKeyDown}
242	        >
243	          {/* All swatches are always in the DOM so screen readers count the full set.
244	              Off-page swatches are visually hidden with the SR-safe clip technique
245	              (position:absolute + clip-path) so they remain in the accessibility tree
246	              but take no visual space. display:none would hide them from SR entirely. */}
247	          {swatchVariants.map((variant, globalIndex) => {
248	            const { value, name, imageUrl } = variant;
249	            const isSelected = value === selectedValue;
250	            const indexOnPage = globalIndex - page * PAGE_SIZE;
251	            const isOnCurrentPage = indexOnPage >= 0 && indexOnPage < PAGE_SIZE;
252	            const isTabStop = isOnCurrentPage && (isSelected || (!selectedOnCurrentPage && indexOnPage === 0));
253	
254	            return (
255	              <chakra.button
256	                key={value}
257	                __css={isOnCurrentPage ? styles.swatch : undefined}
258	                style={
259	                  isOnCurrentPage
260	                    ? undefined
261	                    : {
262	                        position: 'absolute',
263	                        width: '1px',
264	                        height: '1px',
265	                        padding: 0,
266	                        margin: '-1px',
267	                        overflow: 'hidden',
268	                        clipPath: 'inset(50%)',
269	                        whiteSpace: 'nowrap',
270	                        border: 0,
271	                      }
272	                }
273	                type="button"
274	                ref={(el: HTMLButtonElement | null) => {
275	                  if (isOnCurrentPage) swatchRefs.current[indexOnPage] = el;
276	                }}
277	                role="radio"
278	                aria-checked={isSelected}
279	                aria-label={name}
280	                tabIndex={isTabStop ? 0 : -1}
281	                data-testid={`pdp-colour-swatch-${value}`}
282	                data-swatch-value={value}
283	                // Selected swatch paints above siblings — zIndex driven by selection state.
284	                sx={isOnCurrentPage ? { zIndex: isSelected ? 1 : undefined } : undefined}
285	                onClick={() => onSelect(value)}
286	              >
287	                {/* imageUrl is typed `string` here via OfferedColourVariant, not merely assumed non-null. */}
288	                <chakra.div __css={styles.swatchImage}>
289	                  <img
290	                    src={sizedSwatchUrl(imageUrl)}
291	                    alt={name}
292	                    loading="lazy"
293	                    width={SWATCH_IMAGE_WIDTH}
294	                    height={SWATCH_IMAGE_HEIGHT}
295	                    style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
296	                  />
297	                </chakra.div>
298	                {isSelected && <chakra.div __css={styles.selectedIndicator} />}
299	              </chakra.button>
300	            );
301	          })}
302	        </chakra.div>
303	      )}
304	    </chakra.div>
305	  );
306	};
307	
308	export type { ColourVariant, ColourSwatchesProps };
309	export { ColourSwatches };
310	export default ColourSwatches;
